// Change "Serial1." to "Serial." if using Arduino Uno instead of SSTuino.


// Declare the constants and variables

#define ledPin 12

int data = 0;


  // Turn LED off at the start and set the serial monitor baud rate

void setup() {

  pinMode(ledPin, OUTPUT);

  digitalWrite(ledPin, LOW);

  Serial1.begin(9600); 

}


void loop() {

  if(Serial1.available() > 0){ // Checks whether data is comming from the serial port

    data = Serial1.read(); // Reads the data from the serial port

             if (data == '0') {

            digitalWrite(ledPin, LOW);  // Turn LED OFF

            Serial1.println("LED: OFF");

            }

              else if (data == '1') {

                digitalWrite(ledPin, HIGH); // Turn LED ON

                Serial1.println("LED: ON");

              }

  }

}

