#include <LiquidCrystal_I2C.h>

int Temp = 0;

LiquidCrystal_I2C lcd_1(39, 16, 2);

void setup()
{
  lcd_1.init();
  pinMode(A0, INPUT);
  Serial.begin(9600);

  lcd_1.backlight();
  lcd_1.clear();
  lcd_1.print("Temperature");
}

void loop()
{
  Temp = (-40 + 0.488155 * (analogRead(A0) - 20));
  Serial.print(Temp);
  Serial.println("°C");
  lcd_1.setCursor(0, 1);
  lcd_1.print(Temp);
  lcd_1.print("°C");
  delay(2000); // Wait for 2000 millisecond(s)
}

